"""Headline analysis: per-seed tables, paired bootstrap CIs,
figure/non-figure subgroups, seed-ensemble. Reads per-item prediction files from
results/main; writes results/analysis/RESULTS.md.
"""
import os, sys, json, glob
import numpy as np
import pandas as pd

sys.path.insert(0, os.path.dirname(__file__))
from vdiff_utils import RESULTS_DIR

FINAL = os.path.join(RESULTS_DIR, 'main')
OUT_MD = os.path.join(RESULTS_DIR, 'analysis', 'RESULTS.md')
N_BOOT = 10000
RNG = np.random.default_rng(20260725)

TEXT_ORDER = ['Qwen2.5-3B', 'Llama-3.2-3B', 'Qwen3-4B', 'Qwen2.5-7B',
              'Qwen3-8B', 'Llama-3.1-8B']
VLM_ORDER = ['Qwen2.5-VL-3B-Instruct', 'Qwen2.5-VL-7B-Instruct',
             'InternVL2_5-4B', 'paligemma2-3b-pt-224',
             'Qwen3-VL-4B-Instruct', 'Qwen3-VL-8B-Instruct',
             'InternVL3-2B', 'InternVL3-8B', 'InternVL3_5-4B', 'InternVL3_5-8B']


def load_runs(block):
    """-> {(model_dirtag, route): {seed: df}} keyed by the run directory name."""
    out = {}
    for p in glob.glob(os.path.join(FINAL, block, '*', 'seed*', 'test_predictions.csv')):
        df = pd.read_csv(p)
        rj = json.load(open(os.path.join(os.path.dirname(p), 'results.json')))
        dirtag = p.split('/')[-3]
        key = (dirtag, rj['route'])
        out.setdefault(key, {})[rj['seed']] = df.sort_values('item_id').reset_index(drop=True)
    return out


def rmse(a, b):
    return float(np.sqrt(np.mean((np.asarray(a) - np.asarray(b)) ** 2)))


def seed_stats(runs):
    """per-seed rmse list, seed-mean/sd, and seed-ensemble rmse + frame."""
    rmses, sps = [], []
    preds = None
    for seed, df in sorted(runs.items()):
        rmses.append(rmse(df['pred_beta'], df['gold_beta']))
        from scipy import stats as st
        sps.append(float(st.spearmanr(df['pred_beta'], df['gold_beta'])[0]))
        preds = df['pred_beta'].to_numpy() if preds is None else preds + df['pred_beta'].to_numpy()
    base = sorted(runs.items())[0][1]
    ens = base.copy()
    ens['pred_beta'] = preds / len(runs)
    return {
        'n_seeds': len(runs),
        'rmse_mean': float(np.mean(rmses)), 'rmse_sd': float(np.std(rmses)),
        'sp_mean': float(np.mean(sps)), 'sp_sd': float(np.std(sps)),
        'ens_rmse': rmse(ens['pred_beta'], ens['gold_beta']),
        'ens_frame': ens,
    }


def paired_bootstrap(fA, fB):
    """ΔRMSE(B−A) on seed-ensemble predictions, item-level bootstrap 95% CI."""
    m = fA.merge(fB, on='item_id', suffixes=('_a', '_b'))
    ea = (m['pred_beta_a'] - m['gold_beta_a']).to_numpy() ** 2
    eb = (m['pred_beta_b'] - m['gold_beta_b']).to_numpy() ** 2
    n = len(m)
    idx = RNG.integers(0, n, size=(N_BOOT, n))
    da = np.sqrt(ea[idx].mean(axis=1))
    db = np.sqrt(eb[idx].mean(axis=1))
    diff = db - da
    point = float(np.sqrt(eb.mean()) - np.sqrt(ea.mean()))
    lo, hi = np.percentile(diff, [2.5, 97.5])
    return point, float(lo), float(hi)


def subgroup(f):
    fig = f[f['has_figure']]
    non = f[~f['has_figure']]
    return rmse(fig['pred_beta'], fig['gold_beta']), rmse(non['pred_beta'], non['gold_beta'])


def fmt(x):
    return f'{x:+.4f}' if isinstance(x, float) else str(x)


def main():
    from scipy import stats as st  # noqa
    lines = ['# Final three-seed results (generated by analysis/aggregate_results.py)', '',
             f'Bootstrap: {N_BOOT} resamples, item-level, seed-ensemble predictions.', '']

    b2 = load_runs('llm')
    b6 = load_runs('vlm')

    # ---------------- text main table ----------------
    lines += ['## Text models (Q vs Q+D)', '',
              '| Model | Q RMSE (3s) | Q Spearman (3s) | Q+D RMSE (3s) | Q+D Spearman (3s) | Q ens | Q+D ens | ΔRMSE(Q+D−Q) ens [95% CI] |',
              '|---|---|---|---|---|---|---|---|']
    text_stats = {}
    for mod in TEXT_ORDER:
        row = {}
        for dirtag, route in list(b2.keys()):
            if dirtag.endswith('_text_vd'):
                base = dirtag[:-len('_text_vd')]
            elif dirtag.endswith('_text'):
                base = dirtag[:-len('_text')]
            else:
                continue
            base = base.split('_', 1)[-1]
            if base == mod:
                row[route] = seed_stats(b2[(dirtag, route)])
        if 'Q' not in row or 'Q+D' not in row:
            continue
        text_stats[mod] = row
        d, lo, hi = paired_bootstrap(row['Q']['ens_frame'], row['Q+D']['ens_frame'])
        sig = '\\*' if hi < 0 or lo > 0 else ''
        lines.append(
            f"| {mod} | {row['Q']['rmse_mean']:.4f}±{row['Q']['rmse_sd']:.4f} "
            f"| {row['Q']['sp_mean']:.4f}±{row['Q']['sp_sd']:.4f} "
            f"| {row['Q+D']['rmse_mean']:.4f}±{row['Q+D']['rmse_sd']:.4f} "
            f"| {row['Q+D']['sp_mean']:.4f}±{row['Q+D']['sp_sd']:.4f} "
            f"| {row['Q']['ens_rmse']:.4f} | {row['Q+D']['ens_rmse']:.4f} "
            f"| {fmt(d)} [{lo:+.4f}, {hi:+.4f}]{sig} |")
    lines.append('')

    # ---------------- VLM main table ----------------
    def vlm_rows(suffix=''):
        rows = {}
        for mod in VLM_ORDER:
            row = {}
            for dirtag, route in list(b6.keys()):
                for rt, tag in [('I', '_I'), ('I+Q', '_IQ'), ('I+Q+D', '_IQD')]:
                    if dirtag.endswith(tag + suffix) and dirtag[:-len(tag + suffix)].endswith(mod.replace('/', '_')):
                        if route == rt:
                            row[rt] = seed_stats(b6[(dirtag, route)])
            if row:
                rows[mod] = row
        return rows

    for suffix, title in [('', 'VLM models (I / I+Q / I+Q+D)'),
                          ('_ep10', 'VLM models, 10-epoch schedule')]:
        rows = vlm_rows(suffix)
        if not rows:
            continue
        lines += [f'## {title}', '',
                  '| Model | I RMSE | I Sp | I+Q RMSE | I+Q Sp | I+Q+D RMSE | I+Q+D Sp | ΔRMSE(I+Q−I) ens [95% CI] |',
                  '|---|---|---|---|---|---|---|---|']
        for mod, row in rows.items():
            cells = []
            for rt in ['I', 'I+Q', 'I+Q+D']:
                if rt in row:
                    cells.append(f"{row[rt]['rmse_mean']:.4f}±{row[rt]['rmse_sd']:.4f}")
                    cells.append(f"{row[rt]['sp_mean']:.4f}±{row[rt]['sp_sd']:.4f}")
                else:
                    cells += ['—', '—']
            ci = '—'
            if 'I' in row and 'I+Q' in row:
                d, lo, hi = paired_bootstrap(row['I']['ens_frame'], row['I+Q']['ens_frame'])
                sig = '\\*' if hi < 0 or lo > 0 else ''
                ci = f'{fmt(d)} [{lo:+.4f}, {hi:+.4f}]{sig}'
            lines.append(f"| {mod} | " + ' | '.join(cells) + f" | {ci} |")
        lines.append('')

    # ---------------- subgroups for key systems ----------------
    lines += ['## Figure / non-figure subgroups (seed-ensemble RMSE)', '',
              '| System | figure(n≈79) | non-figure(n≈66) |', '|---|---|---|']
    keysys = []
    if 'Qwen3-4B' in text_stats:
        keysys += [('Qwen3-4B Q', text_stats['Qwen3-4B']['Q']['ens_frame']),
                   ('Qwen3-4B Q+D', text_stats['Qwen3-4B']['Q+D']['ens_frame'])]
    for mod in ['Qwen2.5-VL-7B-Instruct', 'Qwen3-VL-8B-Instruct']:
        r = vlm_rows().get(mod, {})
        for rt in ['I', 'I+Q']:
            if rt in r:
                keysys.append((f'{mod} {rt}', r[rt]['ens_frame']))
    for name, f in keysys:
        fg, ng = subgroup(f)
        lines.append(f'| {name} | {fg:.4f} | {ng:.4f} |')
    lines.append('')

    with open(OUT_MD, 'w') as f:
        f.write('\n'.join(lines))
    print(f'written: {OUT_MD}')


if __name__ == '__main__':
    main()
